        if in_d and esc:
            out.append(ch); esc = False; continue
        if in_d and ch == '\\':
            out.append(ch); esc = True; continue
        if ch == "'" and not in_d:
            in_s = not in_s; out.append(ch); continue
        if ch == '"' and not in_s:
