    if v == 'true':
        return True
    if v == 'false':
        return False
    if len(v) >= 2 and v[0] in "'\"" and v[-1] == v[0]:
        return _parse_toml_string(v)
    if v.startswith('[') and v.endswith(']'):
        inner = v[1:-1].strip()
        if not inner:
            return []
        parts = []
        cur = ''
        in_s = in_d = False
        esc = False
        for ch in inner:
            if in_d and esc:
                cur += ch; esc = False; continue
            if in_d and ch == '\\':
                cur += ch; esc = True; continue
            if ch == "'" and not in_d:
                in_s = not in_s; cur += ch; continue
            if ch == '"' and not in_s:
                in_d = not in_d; cur += ch; continue
            if ch == ',' and not in_s and not in_d:
                parts.append(cur.strip()); cur = ''; continue
            cur += ch
        if cur.strip() or inner.endswith(','):
            parts.append(cur.strip())
        return [_parse_toml_value(p) for p in parts if p != '']
    try:
        if v and all(c in '+-0123456789_' for c in v):
            return int(v.replace('_',''))
    except ValueError:
        pass
    raise SimpleTomlError('invalid value')

def _parse_toml_key(k: str) -> str:
    k = k.strip()
    if len(k) >= 2 and k[0] in "'\"" and k[-1] == k[0]:
        return _parse_toml_string(k)
    if not k:
        raise SimpleTomlError('empty key')
    return k

def parse_simple_toml_file(path: str) -> dict:
    root: dict = {}
    cur = root
    with open(path, 'r', encoding='utf-8') as f:
        for lineno, raw in enumerate(f, 1):
            line = _strip_toml_comment(raw.rstrip('\n'))
            if not line:
                continue
            if line.startswith('[') and line.endswith(']') and line.count('[') == 1:
                sec = line[1:-1].strip()
                if not sec:
                    raise SimpleTomlError(f'at line {lineno}: empty table')
                cur = root.setdefault(sec, {})
                if not isinstance(cur, dict):
                    raise SimpleTomlError(f'at line {lineno}: duplicate table')
                continue
            if '=' not in line:
                raise SimpleTomlError(f'at line {lineno}: expected `=`')
            k, v = line.split('=', 1)
            key = _parse_toml_key(k)
            val = _parse_toml_value(v)
            cur[key] = val
    return root

'''
